   135	Caml_inline char caml_gc_phase_char(int may_access_gc_phase) {
   136	  if (!may_access_gc_phase)
   137	    return 'U';
   138	  switch (caml_gc_phase) {
   139	    case Phase_sweep_and_mark_main:
   140	      return 'M';
   141	    case Phase_mark_final:
   142	      return 'F';
   143	    case Phase_sweep_ephe:
   144	      return 'E';
   145	    default:
   146	      return 'U';
   147	  }
   148	}
