   483	void caml_orphan_ephemerons (caml_domain_state* domain_state)
   484	{
   485	  struct caml_ephe_info* ephe_info = domain_state->ephe_info;
   486	  if (ephe_info->todo == 0 &&
   487	      ephe_info->live == 0 &&
   488	      ephe_info->must_sweep_ephe == 0)
   489	    return;
   490	
   491	  /* Force all ephemerons and their data on todo list to be alive */
   492	  if (ephe_info->todo) {
   493	    while (ephe_info->todo) {
   494	      ephe_mark (100000, 0, EPHE_MARK_FORCE_ALIVE);
   495	    }
   496	    ephe_todo_list_emptied ();
   497	  }
   498	  CAMLassert (ephe_info->todo == 0);
   499	
   500	  if (ephe_info->live) {
   501	    value live_tail = ephe_list_tail(ephe_info->live);
   502	    CAMLassert(Ephe_link(live_tail) == 0);
   503	
   504	    caml_plat_lock_blocking(&orphaned_lock);
   505	    Ephe_link(live_tail) = orph_structs.ephe_list_live;
   506	    orph_structs.ephe_list_live = ephe_info->live;
   507	    ephe_info->live = 0;
   508	    caml_plat_unlock(&orphaned_lock);
   509	  }
   510	
   511	  if (ephe_info->must_sweep_ephe) {
   512	    ephe_info->must_sweep_ephe = 0;
   513	    (void)caml_atomic_counter_decr(&num_domains_to_ephe_sweep);
   514	  }
   515	  CAMLassert (ephe_info->must_sweep_ephe == 0);
   516	  CAMLassert (ephe_info->live == 0);
   517	  CAMLassert (ephe_info->todo == 0);
   518	}
   519	
   520	void caml_orphan_finalisers (caml_domain_state* domain_state)
   521	{
   522	  struct caml_final_info* f = domain_state->final_info;
   523	
   524	  if (f->todo_head != NULL || f->first.size != 0 || f->last.size != 0) {
   525	    /* have some final structures */
   526	    (void)caml_atomic_counter_incr(&num_domains_orphaning_finalisers);
   527	    if (caml_gc_phase != Phase_sweep_and_mark_main) {
   528	      /* Force a major GC cycle to simplify constraints for orphaning
   529	         finalisers. See note attached to the declaration of
   530	         [num_domains_orphaning_finalisers] variable in major_gc.c */
   531	      caml_finish_major_cycle(0);
   532	    }
   533	    CAMLassert(caml_gc_phase == Phase_sweep_and_mark_main);
   534	    CAMLassert (!f->updated_first);
   535	    CAMLassert (!f->updated_last);
   536	
   537	    /* Add the finalisers to [orph_structs] */
   538	    caml_plat_lock_blocking(&orphaned_lock);
   539	    f->next = orph_structs.final_info;
   540	    orph_structs.final_info = f;
   541	    caml_plat_unlock(&orphaned_lock);
   542	
   543	    /* Create a dummy final info */
   544	    f = domain_state->final_info = caml_alloc_final_info();
   545	    (void)caml_atomic_counter_decr(&num_domains_orphaning_finalisers);
   546	  }
   547	
   548	  /* [caml_orphan_finalisers] is called in a while loop in
   549	     [caml_domain_terminate].
   550	     We take care to decrement the [num_domains_to_final_update*] counters only
   551	     if we have not already decremented it for the current cycle. */
   552	  if(!f->updated_first) {
   553	    (void)caml_atomic_counter_decr(&num_domains_to_final_update_first);
   554	    f->updated_first = 1;
   555	  }
   556	  if(!f->updated_last) {
   557	    (void)caml_atomic_counter_decr(&num_domains_to_final_update_last);
   558	    f->updated_last = 1;
   559	  }
   560	}
   561	
   562	static int no_orphaned_work (void)
   563	{
   564	  return
   565	    atomic_load_acquire(&orph_structs.ephe_list_live) == 0 &&
   566	    atomic_load_acquire(&orph_structs.final_info) == NULL;
   567	}
   568	
   569	static void adopt_orphaned_work (void)
   570	{
   571	  caml_domain_state* domain_state = Caml_state;
   572	  value orph_ephe_list_live, last;
   573	  struct caml_final_info *f, *myf, *temp;
   574	
   575	  if (no_orphaned_work() || caml_domain_is_terminating())
   576	    return;
   577	
   578	  caml_plat_lock_blocking(&orphaned_lock);
   579	
   580	  orph_ephe_list_live = orph_structs.ephe_list_live;
   581	  orph_structs.ephe_list_live = 0;
   582	
   583	  f = orph_structs.final_info;
   584	  orph_structs.final_info = NULL;
   585	
   586	  caml_plat_unlock(&orphaned_lock);
   587	
   588	  if (orph_ephe_list_live) {
   589	    last = ephe_list_tail(orph_ephe_list_live);
   590	    CAMLassert(Ephe_link(last) == 0);
   591	    Ephe_link(last) = domain_state->ephe_info->live;
   592	    domain_state->ephe_info->live = orph_ephe_list_live;
   593	  }
   594	
   595	  while (f != NULL) {
   596	    myf = domain_state->final_info;
   597	    CAMLassert (caml_gc_phase == Phase_sweep_and_mark_main);
   598	    /* Since we are in [Phase_sweep_and_mark_main], the current domain has not
   599	       updated its finalisers. */
   600	    CAMLassert (!myf->updated_first);
   601	    CAMLassert (!myf->updated_last);
   602	
   603	    if (f->todo_head) {
   604	      /* Adopt the finalising set. */
   605	      if (myf->todo_tail == NULL) {
   606	        CAMLassert(myf->todo_head == NULL);
   607	        myf->todo_head = f->todo_head;
   608	        myf->todo_tail = f->todo_tail;
   609	      } else {
   610	        myf->todo_tail->next = f->todo_head;
   611	        myf->todo_tail = f->todo_tail;
   612	      }
   613	    }
   614	
   615	    /* Adopt the finalisable set */
   616	    if (f->first.young > 0) {
   617	      caml_final_merge_finalisable (&f->first, &myf->first);
   618	    }
   619	    if (f->last.young > 0) {
   620	      caml_final_merge_finalisable (&f->last, &myf->last);
   621	    }
   622	
   623	    temp = f;
   624	    f = f->next;
   625	    caml_stat_free (temp);
   626	  }
   627	}
   628	
   629	/*******************************************************************************
   630	 * Pacing
   631	 ******************************************************************************/
   632	
   633	/* These two counters keep track of how much work the GC is supposed to
   634	   do in order to keep up with allocation. Both are in GC work units.
   635	   `alloc_counter` increases when we allocate: the number of words allocated
   636	   is converted to GC work units and added to this counter.
   637	   `work_counter` increases when the GC has done some work.
   638	   The difference between the two is how much the GC is lagging behind
   639	   (or in advance of) allocations.
   640	   These counters can wrap around (see function `diffmod`) as long as they
   641	   don't get too far apart, which is guaranteed by the limited size of
   642	   memory.
   643	*/
   644	static atomic_uintnat alloc_counter;
   645	static atomic_uintnat work_counter;
   646	
   647	static inline intnat max2 (intnat a, intnat b)
   648	{
   649	  if (a > b){
   650	    return a;
   651	  }else{
   652	    return b;
   653	  }
   654	}
   655	
   656	static inline intnat min2 (intnat a, intnat b)
   657	{
   658	  if (a < b){
   659	    return a;
   660	  }else{
   661	    return b;
   662	  }
   663	}
   664	
   665	static inline intnat max3(intnat a, intnat b, intnat c)
   666	{
   667	  if (a > b){
   668	    return max2 (a, c);
   669	  }else{
   670	    return max2 (b, c);
   671	  }
   672	}
   673	
   674	/* Take two natural numbers n1 and n2 and let N = 2^{64}.
   675	   Assume that n1 and n2 are not too far apart (less than N/2).
   676	   Given unsigned numbers x1 = n1 modulo N and x2 = n2 modulo N, return
   677	   the (signed) difference between n1 and n2.
   678	*/
   679	static inline intnat diffmod (uintnat x1, uintnat x2)
   680	{
   681	  return (intnat) (x1 - x2);
   682	}
   683	
   684	/* Reset the work and alloc counters to be equal to each other, by
   685	 * setting them both equal to the "larger" (in the wrapping-around
   686	 * sense we are using here for work_counter and alloc_counter).
   687	 *
   688	 * For use at times when we have disturbed the major GC from its usual
   689	 * pacing and tempo, for example, after any synchronous major
   690	 * collection.
   691	 */
   692	
   693	void caml_reset_major_pacing(void)
   694	{
   695	  bool res;
   696	  do {
   697	    uintnat alloc = atomic_load(&alloc_counter);
   698	    uintnat work = atomic_load(&work_counter);
   699	    uintnat target = alloc;
   700	    if (diffmod(work, alloc) > 0) {
   701	      target = work;
   702	    }
   703	    res = (atomic_compare_exchange_strong(&alloc_counter, &alloc, target) &&
   704	           atomic_compare_exchange_strong(&work_counter, &work, target));
   705	  } while (!res);
   706	}
   707	
   708	/* The [log_events] parameter is used to disable writing to the ring for two
   709	   reasons:
   710	   1. To prevent spamming the ring with numerous events generated during
   711	      an opportunistic GC slice.
   712	   2. To avoid logging events when the calling domain is not part of the
   713	      Stop-The-World (STW) participant set. If the domain is not part of
   714	      the STW set, the ring could be torn down concurrently while this domain
   715	      attempts to write to it. */
   716	static void
   717	update_major_slice_work(intnat howmuch,
   718	                        int may_access_gc_phase,
   719	                        int log_events /* log events to the ring? */)
   720	{
   721	  intnat alloc_work, dependent_work, extra_work, new_work;
   722	  intnat my_alloc_count, my_alloc_direct_count, my_dependent_count;
   723	  intnat my_alloc_suspended_count, my_alloc_resumed_count;
   724	  double my_extra_count;
   725	  caml_domain_state *dom_st = Caml_state;
   726	  uintnat heap_words, heap_size, heap_sweep_words, total_cycle_work;
   727	  uintnat percent_free;
   728	
   729	  my_alloc_count = dom_st->allocated_words;
   730	  my_alloc_direct_count = dom_st->allocated_words_direct;
   731	  my_alloc_suspended_count = dom_st->allocated_words_suspended;
   732	  my_alloc_resumed_count = dom_st->allocated_words_resumed;
   733	  my_dependent_count = dom_st->dependent_allocated;
   734	  my_extra_count = dom_st->extra_heap_resources;
   735	
   736	  dom_st->stat_major_words += dom_st->allocated_words;
   737	  dom_st->current_ramp_up_allocated_words_diff +=
   738	    dom_st->allocated_words_suspended;
   739	
   740	  dom_st->allocated_words = 0;
   741	  dom_st->allocated_words_direct = 0;
   742	  dom_st->allocated_words_suspended = 0;
   743	  dom_st->allocated_words_resumed = 0;
   744	  dom_st->dependent_allocated = 0;
   745	  dom_st->extra_heap_resources = 0.0;
   746	
   747	  /*
   748	     Free memory at the start of the GC cycle (garbage + free list) (assumed):
   749	                 FM = heap_words * caml_percent_free
   750	                      / (100 + caml_percent_free)
   751	
   752	     Assuming steady state and enforcing a constant allocation rate, then
   753	     FM is divided in 2/3 for garbage and 1/3 for free list.
   754	              G = 2 * FM / 3
   755	     G is also the amount of memory that will be used during this cycle
   756	     (still assuming steady state).
   757	
   758	     Proportion of G consumed since the previous slice:
   759	              PH = dom_st->allocated_words / G
   760	                = dom_st->allocated_words * 3 * (100 + caml_percent_free)
   761	                  / (2 * heap_words * caml_percent_free)
   762	     Proportion of extra-heap resources consumed since the previous slice:
   763	              PE = dom_st->extra_heap_resources
   764	     Proportion of total work to do in this slice:
   765	              P  = max (PH, PE)
   766	     Amount of marking work for the GC cycle:
   767	              MW = heap_words * 100 / (100 + caml_percent_free)
   768	     Amount of sweeping work for the GC cycle:
   769	              SW = heap_sweep_words
   770	     Amount of total work for the GC cycle:
   771	              TW = MW + SW
   772	              = heap_words * 100 / (100 + caml_percent_free) + heap_sweep_words
   773	
   774	     Amount of time to spend on this slice:
   775	                 T = P * TT
   776	
   777	     Since we must do TW amount of work in TT time, the amount of work done
   778	     for this slice is:
   779	                 S = P * TW
   780	  */
   781	  heap_size = caml_heap_size(dom_st->shared_heap);
   782	  heap_words = Wsize_bsize(heap_size);
   783	  heap_sweep_words = heap_words;
   784	  percent_free = atomic_load(&caml_percent_free);
   785	
   786	  total_cycle_work =
   787	    heap_sweep_words
   788	    + (uintnat) ((double) heap_words * 100.0 / (100.0 + percent_free));
   789	
   790	  if (heap_words > 0) {
   791	    double alloc_ratio =
   792	      total_cycle_work
   793	      * 3.0 * (100 + percent_free)
   794	      / heap_words / percent_free / 2.0;
   795	    intnat current_alloc_count =
   796	      my_alloc_count - my_alloc_suspended_count + my_alloc_resumed_count;
   797	    CAMLassert (current_alloc_count >= 0);
   798	    alloc_work = (intnat) (current_alloc_count * alloc_ratio);
   799	  } else {
   800	    alloc_work = 0;
   801	  }
   802	
   803	  if (dom_st->dependent_size > 0) {
   804	    double dependent_ratio =
   805	      total_cycle_work
   806	      * (100 + percent_free)
   807	        / (double)dom_st->dependent_size / (double)percent_free;
   808	    dependent_work = (intnat) (my_dependent_count * dependent_ratio);
   809	  }else{
   810	    dependent_work = 0;
   811	  }
   812	
   813	  extra_work = (intnat) (my_extra_count * (double) total_cycle_work);
   814	
   815	  CAML_GC_MESSAGE(SLICESIZE, "heap_words = %" CAML_PRIuNAT "\n",
   816	                  heap_words);
   817	  CAML_GC_MESSAGE(SLICESIZE, "allocated_words = %" CAML_PRIuNAT "\n",
   818	                   my_alloc_count);
   819	  CAML_GC_MESSAGE(SLICESIZE, "allocated_words_direct = %" CAML_PRIuNAT "\n",
   820	                   my_alloc_direct_count);
   821	  CAML_GC_MESSAGE(SLICESIZE, "allocated_words_suspended = %" CAML_PRIuNAT "\n",
   822	                   my_alloc_suspended_count);
   823	  CAML_GC_MESSAGE(SLICESIZE, "allocated_words_resumed = %" CAML_PRIuNAT "\n",
   824	                   my_alloc_resumed_count);
   825	  CAML_GC_MESSAGE(SLICESIZE, "alloc work-to-do = %" CAML_PRIdNAT "\n",
   826	                   alloc_work);
   827	  CAML_GC_MESSAGE(SLICESIZE, "dependent_words = %" CAML_PRIuNAT "\n",
   828	                   my_dependent_count);
   829	  CAML_GC_MESSAGE(SLICESIZE, "dependent work-to-do = %" CAML_PRIdNAT "\n",
   830	                  dependent_work);
   831	  CAML_GC_MESSAGE(SLICESIZE, "extra_heap_resources = %" CAML_PRIuNAT "u\n",
   832	                  (uintnat) (my_extra_count * 1000000));
   833	  CAML_GC_MESSAGE(SLICESIZE, "extra work-to-do = %" CAML_PRIdNAT "\n",
   834	                  extra_work);
   835	
   836	  new_work = max3 (alloc_work, dependent_work, extra_work);
   837	  atomic_fetch_add (&work_counter, dom_st->major_work_done_between_slices);
   838	  dom_st->major_work_done_between_slices = 0;
   839	  atomic_fetch_add (&alloc_counter, new_work);
   840	  if (howmuch == AUTO_TRIGGERED_MAJOR_SLICE ||
   841	      howmuch == GC_CALCULATE_MAJOR_SLICE) {
   842	    dom_st->slice_target = atomic_load (&alloc_counter);
   843	    dom_st->slice_budget = 0;
   844	  }else{
   845	    /* forced or opportunistic GC slice with explicit quantity */
   846	    dom_st->slice_target = atomic_load (&work_counter);  /* already reached */
   847	    dom_st->slice_budget = howmuch;
   848	  }
   849	
   850	  caml_gc_log("Updated major work: [%c] "
   851	              " %" CAML_PRIuNAT " heap_words, "
   852	              " %" CAML_PRIuNAT " allocated, "
   853	              " %" CAML_PRIuNAT " allocated (direct), "
   854	              " %" CAML_PRIuNAT " allocated (suspended), "
   855	              " %" CAML_PRIuNAT " allocated (resumed), "
   856	              " %" CAML_PRIdNAT " alloc_work, "
   857	              " %" CAML_PRIdNAT " dependent_work, "
   858	              " %" CAML_PRIdNAT " extra_work, "
   859	              " %" CAML_PRIuNAT " work counter %s, "
   860	              " %" CAML_PRIuNAT " alloc counter, "
   861	              " %" CAML_PRIuNAT " slice target, "
   862	              " %" CAML_PRIdNAT " slice budget"
   863	              ,
   864	              caml_gc_phase_char(may_access_gc_phase),
   865	              heap_words, my_alloc_count, my_alloc_direct_count,
   866	              my_alloc_suspended_count, my_alloc_resumed_count,
   867	              alloc_work, dependent_work, extra_work,
   868	              atomic_load (&work_counter),
   869	              atomic_load (&work_counter) > atomic_load (&alloc_counter)
   870	                ? "[ahead]" : "[behind]",
   871	              atomic_load (&alloc_counter),
   872	              dom_st->slice_target, dom_st->slice_budget
   873	              );
   874	
   875	  if (log_events) {
   876	    CAML_EV_COUNTER(EV_C_MAJOR_HEAP_WORDS, (uintnat)heap_words);
   877	    CAML_EV_COUNTER(EV_C_MAJOR_ALLOCATED_WORDS, my_alloc_count);
   878	    /* TODO: add counters for direct, suspended, resumed allocs. */
   879	    CAML_EV_COUNTER(EV_C_MAJOR_ALLOCATED_WORK, alloc_work);
   880	    CAML_EV_COUNTER(EV_C_MAJOR_DEPENDENT_WORK, dependent_work);
   881	    CAML_EV_COUNTER(EV_C_MAJOR_EXTRA_WORK, extra_work);
   882	    CAML_EV_COUNTER(EV_C_MAJOR_WORK_COUNTER, atomic_load (&work_counter));
   883	    CAML_EV_COUNTER(EV_C_MAJOR_ALLOC_COUNTER, atomic_load (&alloc_counter));
   884	    CAML_EV_COUNTER(EV_C_MAJOR_SLICE_TARGET, dom_st->slice_target);
   885	    CAML_EV_COUNTER(EV_C_MAJOR_SLICE_BUDGET, dom_st->slice_budget);
   886	  }
   887	}
   888	
   889	#define Chunk_size 0x4000
   890	
   891	typedef enum {
   892	  Slice_uninterruptible,
   893	  Slice_interruptible,
   894	  Slice_opportunistic
   895	} collection_slice_mode;
   896	
   897	static intnat get_major_slice_work(collection_slice_mode mode){
   898	  caml_domain_state *dom_st = Caml_state;
   899	
   900	  if (mode == Slice_interruptible && caml_incoming_interrupts_queued())
   901	    return 0;
   902	
   903	  /* calculate how much work remains to do for this slice */
   904	  intnat budget =
   905	    max2 (diffmod (dom_st->slice_target, atomic_load (&work_counter)),
   906	          dom_st->slice_budget);
   907	  return min2(budget, Chunk_size);
   908	}
   909	
   910	/* Register the work done by a chunk of slice.
   911	   Clear requested_global_major_slice if the work counter has caught up with
   912	   the slice's target counter. */
   913	static void commit_major_slice_work(intnat words_done) {
   914	  caml_domain_state *dom_st = Caml_state;
   915	
   916	  caml_gc_log ("Commit major slice work:  %" CAML_PRIdNAT " words_done, ",
   917	               words_done);
   918	
   919	  dom_st->slice_budget -= words_done;
   920	  atomic_fetch_add (&work_counter, words_done);
   921	  if (diffmod (dom_st->slice_target, atomic_load (&work_counter)) <= 0){
   922	    /* We've done enough work by ourselves, no need to interrupt the other
   923	       domains. */
   924	    dom_st->requested_global_major_slice = 0;
   925	  }
   926	}
