   928	/*******************************************************************************
   929	 * Marking
   930	 ******************************************************************************/
   931	
   932	/* NB the MARK_STACK_INIT_SIZE must be larger than the number of objects
   933	   that can be in a pool, see POOL_WSIZE */
   934	#define MARK_STACK_INIT_SIZE (1 << 12)
   935	
   936	/* The mark stack consists of two parts:
   937	   1. the stack - a dynamic array of spans of fields that need to be marked, and
   938	   2. the compressed stack - a bitset of fields that need to be marked.
   939	
   940	   The stack is bounded relative to the heap size. When the stack
   941	   overflows the bound, then entries from the stack are compressed and
   942	   transferred into the compressed stack, expect for "large" entries,
   943	   spans of more than BITS_PER_WORD entries, that are more compactly
   944	   represented as spans and remain on the uncompressed stack.
   945	
   946	   When the stack is empty, the compressed stack is processed.
   947	   The compressed stack iterator marks the point up to which
   948	   compressed stack entries have already been processed.
   949	*/
   950	
   951	typedef struct {
   952	  value_ptr start;
   953	  value_ptr end;
   954	} mark_entry; /* represents fields in the span [start, end) */
   955	
   956	struct mark_stack {
   957	  mark_entry* stack;
   958	  uintnat count;
   959	  uintnat size;
   960	  struct addrmap compressed_stack;
   961	  addrmap_iterator compressed_stack_iter;
   962	};
   963	
   964	#ifdef DEBUG
   965	#define Is_markable(v) \
   966	    (CAMLassert (v != Debug_free_major), \
   967	     Is_block(v) && !Is_young(v))
   968	#else
   969	#define Is_markable(v) (Is_block(v) && !Is_young(v))
   970	#endif
   971	
   972	/* Compressed mark stack
   973	
   974	   We use a bitset, implemented as a hashtable storing word-sized
   975	   integers (uintnat). Each integer represents a "chunk" of addresses
   976	   that may or may not be present in the stack.
   977	 */
   978	static const uintnat chunk_mask = ~(uintnat)(BITS_PER_WORD-1);
   979	static inline uintnat ptr_to_chunk(value_ptr ptr) {
   980	  return ((uintnat)(ptr) / sizeof(value)) & chunk_mask;
   981	}
   982	static inline uintnat ptr_to_chunk_offset(value_ptr ptr) {
   983	  return ((uintnat)(ptr) / sizeof(value)) & ~chunk_mask;
   984	}
   985	static inline value_ptr chunk_and_offset_to_ptr(uintnat chunk, uintnat offset) {
   986	  return (value_ptr)((chunk + offset) * sizeof(value));
   987	}
   988	
   989	Caml_inline int add_addr(struct addrmap* amap, value_ptr ptr) {
   990	  uintnat chunk = ptr_to_chunk(ptr);
   991	  uintnat offset = ptr_to_chunk_offset(ptr);
   992	  uintnat flag = (uintnat)1 << offset;
   993	  int new_entry = 0;
   994	
   995	  value* amap_pos = caml_addrmap_insert_pos(amap, chunk);
   996	
   997	  if (*amap_pos == ADDRMAP_NOT_PRESENT) {
   998	    new_entry = 1;
   999	    *amap_pos = 0;
  1000	  }
  1001	
  1002	  CAMLassert(ptr == chunk_and_offset_to_ptr(chunk, offset));
  1003	
  1004	  if (!(*amap_pos & flag)) {
  1005	    *amap_pos |= flag;
  1006	  }
  1007	
  1008	  return new_entry;
  1009	}
  1010	
  1011	static void mark_stack_prune(struct mark_stack* stk)
  1012	{
  1013	  /* Since addrmap is (currently) using open address hashing, we cannot insert
  1014	     new compressed stack entries into an existing, partially-processed
  1015	     compressed stack. Thus, we create a new compressed stack and insert the
  1016	     unprocessed entries of the existing compressed stack into the new one. */
  1017	  uintnat old_compressed_entries = 0;
  1018	  struct addrmap new_compressed_stack = ADDRMAP_INIT;
  1019	  for (addrmap_iterator it = stk->compressed_stack_iter;
  1020	       caml_addrmap_iter_ok(&stk->compressed_stack, it);
  1021	       it = caml_addrmap_next(&stk->compressed_stack, it)) {
  1022	    value k = caml_addrmap_iter_key(&stk->compressed_stack, it);
  1023	    value v = caml_addrmap_iter_value(&stk->compressed_stack, it);
  1024	    caml_addrmap_insert(&new_compressed_stack, k, v);
  1025	    ++old_compressed_entries;
  1026	  }
  1027	  if (old_compressed_entries > 0) {
  1028	    caml_gc_log("Preserved %" CAML_PRIdNAT " compressed entries",
  1029	                old_compressed_entries);
  1030	  }
  1031	  caml_addrmap_clear(&stk->compressed_stack);
  1032	  stk->compressed_stack = new_compressed_stack;
  1033	
  1034	  /* scan mark stack and compress entries */
  1035	  uintnat new_stk_count = 0, compressed_entries = 0, total_words = 0;
  1036	  for (uintnat i = 0; i < stk->count; i++) {
  1037	    mark_entry me = stk->stack[i];
  1038	    total_words += me.end - me.start;
  1039	    if (me.end - me.start > BITS_PER_WORD) {
  1040	      /* keep entry in the stack as more efficient and move to front */
  1041	      stk->stack[new_stk_count++] = me;
  1042	    } else {
  1043	      while(me.start < me.end) {
  1044	        compressed_entries += add_addr(&stk->compressed_stack,
  1045	                                       me.start);
  1046	        me.start++;
  1047	      }
  1048	    }
  1049	  }
  1050	
  1051	  caml_gc_log("Compressed %" CAML_PRIdNAT " mark stack words into "
  1052	              "%" CAML_PRIdNAT " mark stack entries and "
  1053	              "%" CAML_PRIdNAT " compressed entries",
  1054	              total_words, new_stk_count,
  1055	              compressed_entries+old_compressed_entries);
  1056	
  1057	  stk->count = new_stk_count;
  1058	  CAMLassert(stk->count < stk->size);
  1059	
  1060	  /* setup the compressed stack iterator */
  1061	  stk->compressed_stack_iter = caml_addrmap_iterator(&stk->compressed_stack);
  1062	}
