  1064	static void realloc_mark_stack (struct mark_stack* stk)
  1065	{
  1066	  mark_entry* new;
  1067	  uintnat mark_stack_large_bsize = 0;
  1068	  uintnat mark_stack_bsize = stk->size * sizeof(mark_entry);
  1069	  uintnat local_heap_bsize = caml_heap_size(Caml_state->shared_heap);
  1070	
  1071	  /* When the mark stack might not increase, we count the large mark entries
  1072	     to adjust our alloaction. This is needed because large mark stack entries
  1073	     will not compress and because we are using a domain local heap bound we
  1074	     need to fit large blocks into the local mark stack. See PR#11284 */
  1075	  if (mark_stack_bsize >= local_heap_bsize / 32) {
  1076	    for (uintnat i = 0; i < stk->count; ++i) {
  1077	      mark_entry* me = &stk->stack[i];
  1078	      if (me->end - me->start > BITS_PER_WORD)
  1079	        mark_stack_large_bsize += sizeof(mark_entry);
  1080	    }
  1081	  }
  1082	
  1083	  if (mark_stack_bsize - mark_stack_large_bsize < local_heap_bsize / 32) {
  1084	    uintnat target_bsize = (mark_stack_bsize - mark_stack_large_bsize) * 2
  1085	                              + mark_stack_large_bsize;
  1086	    caml_gc_log ("Growing mark stack to %" CAML_PRIuNAT "k bytes"
  1087	                 "(large block %" CAML_PRIuNAT "k bytes)\n",
  1088	                 target_bsize / 1024, mark_stack_large_bsize / 1024);
  1089	
  1090	    new = (mark_entry*) caml_stat_resize_noexc ((char*) stk->stack,
  1091	                                                target_bsize);
  1092	    if (new != NULL) {
  1093	      stk->stack = new;
  1094	      stk->size = target_bsize / sizeof(mark_entry);
  1095	      return;
  1096	    }
  1097	    caml_gc_log ("No room for growing mark stack. Compressing..\n");
  1098	  }
  1099	
  1100	  caml_gc_log ("Mark stack size is %" CAML_PRIuNAT " bytes (> major heap size "
  1101	               "of this domain %" CAML_PRIuNAT " bytes / 32). Compressing...\n",
  1102	               mark_stack_bsize,
  1103	               local_heap_bsize);
  1104	  mark_stack_prune(stk);
  1105	}
