  1107	/* This function is used for reads that may race with a concurrent `caml_modify`
  1108	   from the mutator. Without this, TSan would flag it as a race (see section
  1109	   3.2 of comment in tsan.c); however, we have decided that these races are
  1110	   benign. We therefore use this function instead, ensuring that the read is
  1111	   not seen by TSan. */
  1112	static CAMLno_tsan
  1113	#if defined(WITH_THREAD_SANITIZER)
  1114	Caml_noinline
  1115	#endif
  1116	value volatile_load_uninstrumented(volatile value* p) {
  1117	  return *p;
  1118	}
  1119	
  1120	Caml_inline void mark_stack_push_range(struct mark_stack* stk,
  1121	                                       value_ptr start, value_ptr end)
  1122	{
  1123	  mark_entry* me;
  1124	
  1125	  if (stk->count == stk->size)
  1126	    realloc_mark_stack(stk);
  1127	
  1128	  me = &stk->stack[stk->count++];
  1129	  me->start = start;
  1130	  me->end = end;
  1131	}
