  1133	/* returns the work done by skipping unmarkable objects */
  1134	static intnat mark_stack_push_block(struct mark_stack* stk, value block)
  1135	{
  1136	  int i, end;
  1137	  uintnat block_wsz = Wosize_val(block), offset = 0;
  1138	
  1139	  if (Tag_val(block) == Closure_tag) {
  1140	    /* Skip the code pointers and integers at beginning of closure;
  1141	       start scanning at the first word of the environment part. */
  1142	    offset = Start_env_closinfo(Closinfo_val(block));
  1143	
  1144	    CAMLassert(offset <= Wosize_val(block)
  1145	      && offset >= Start_env_closinfo(Closinfo_val(block)));
  1146	  }
  1147	
  1148	  CAMLassert(Has_status_val(block, caml_global_heap_state.MARKED));
  1149	  CAMLassert(Is_block(block));
  1150	  CAMLassert(!Is_young(block));
  1151	  CAMLassert(Tag_val(block) != Infix_tag);
  1152	  CAMLassert(Tag_val(block) < No_scan_tag);
  1153	  CAMLassert(Tag_val(block) != Cont_tag);
  1154	
  1155	  /* Optimisation to avoid pushing small, unmarkable objects such as
  1156	     [Some 42] into the mark stack. */
  1157	  end = (block_wsz < 8 ? block_wsz : 8);
  1158	
  1159	  for (i = offset; i < end; i++) {
  1160	    value v = volatile_load_uninstrumented(&Field(block, i));
  1161	
  1162	    if (Is_markable(v))
  1163	      break;
  1164	  }
  1165	
  1166	  if (i == block_wsz){
  1167	    /* nothing left to mark and credit header */
  1168	    return Whsize_wosize(block_wsz - offset);
  1169	  }
  1170	
  1171	  mark_stack_push_range(stk,
  1172	                        Op_val(block) + i,
  1173	                        Op_val(block) + block_wsz);
  1174	
  1175	  /* take credit for the work we skipped due to the optimisation.
  1176	     we will take credit for the header later as part of marking. */
  1177	  return i - offset;
  1178	}
