  1180	/* This function shrinks the mark stack back to the MARK_STACK_INIT_SIZE size
  1181	   and is called at domain termination via caml_finish_marking. */
  1182	void caml_shrink_mark_stack (void)
  1183	{
  1184	  struct mark_stack* stk = Caml_state->mark_stack;
  1185	  intnat init_stack_bsize = MARK_STACK_INIT_SIZE * sizeof(mark_entry);
  1186	  mark_entry* shrunk_stack;
  1187	
  1188	  caml_gc_log ("Shrinking mark stack to %" CAML_PRIuNAT "k bytes\n",
  1189	               init_stack_bsize / 1024);
  1190	
  1191	  shrunk_stack = (mark_entry*) caml_stat_resize_noexc ((char*) stk->stack,
  1192	                                              init_stack_bsize);
  1193	  if (shrunk_stack != NULL) {
  1194	    stk->stack = shrunk_stack;
  1195	    stk->size = MARK_STACK_INIT_SIZE;
