  1203	static void mark_slice_darken(struct mark_stack* stk, value child,
  1204	                              intnat* work)
  1205	{
  1206	  header_t chd;
  1207	
  1208	  if (Is_markable(child)){
  1209	
  1210	  /* This part of the code is duplicated in do_some_marking for performance
  1211	   * reasons.
  1212	   * Changes here should probably be reflected in do_some_marking. */
  1213	  /* Annotating an acquire barrier on the header because TSan does not see the
  1214	   * happens-before relationship established by address dependencies with
  1215	   * initializing writes in shared_heap.c allocation (#12894) */
  1216	    CAML_TSAN_ANNOTATE_HAPPENS_AFTER(Hp_val(child));
  1217	    chd = Hd_val(child);
  1218	    if (Tag_hd(chd) == Infix_tag) {
  1219	      child -= Infix_offset_hd(chd);
  1220	      chd = Hd_val(child);
  1221	    }
  1222	    CAMLassert(!Has_status_hd(chd, caml_global_heap_state.GARBAGE));
  1223	    if (Has_status_hd(chd, caml_global_heap_state.UNMARKED)){
  1224	      Caml_state->stat_blocks_marked++;
  1225	      if (Tag_hd(chd) == Cont_tag){
  1226	        caml_darken_cont(child);
  1227	        *work -= Wosize_hd(chd);
  1228	      } else {
  1229	    again:
  1230	        if (Tag_hd(chd) == Lazy_tag || Tag_hd(chd) == Forcing_tag){
  1231	          if(!atomic_compare_exchange_strong(Hp_atomic_val(child), &chd,
  1232	                With_status_hd(chd, caml_global_heap_state.MARKED))){
  1233	                  chd = Hd_val(child);
  1234	                  goto again;
  1235	          }
  1236	        } else {
  1237	          atomic_store_relaxed(
  1238	            Hp_atomic_val(child),
  1239	            With_status_hd(chd, caml_global_heap_state.MARKED));
  1240	        }
  1241	        if(Tag_hd(chd) < No_scan_tag){
  1242	          *work -= mark_stack_push_block(stk, child);
  1243	        } else {
  1244	          *work -= Wosize_hd(chd);
  1245	        }
  1246	      }
  1247	    }
  1248	  }
  1249	}
  1250	
  1251	Caml_noinline static intnat do_some_marking(struct mark_stack* stk,
  1252	                                            intnat budget) {
  1253	  prefetch_buffer_t pb = { .enqueued = 0, .dequeued = 0,
  1254	                           .waterline = PREFETCH_BUFFER_MIN };
  1255	  mark_entry me;
  1256	  /* These global values are cached in locals,
  1257	     so that they can be stored in registers */
  1258	  struct global_heap_state heap_state = caml_global_heap_state;
  1259	  uintnat blocks_marked = 0;
  1260	
  1261	  while (1) {
  1262	    if (pb_above_waterline(&pb)) {
  1263	      /* Dequeue from prefetch buffer */
  1264	      value block = pb_pop(&pb);
  1265	      CAMLassert(Is_markable(block));
  1266	
  1267	      /* This part of the code is a duplicate of mark_slice_darken for
  1268	       * performance reasons.
  1269	       * Changes here should probably be reflected here in mark_slice_darken.*/
  1270	      /* Annotating an acquire barrier on the header because TSan does not see
  1271	       * the happens-before relationship established by address dependencies
  1272	       * with initializing writes in shared_heap.c allocation (#12894) */
  1273	      CAML_TSAN_ANNOTATE_HAPPENS_AFTER(Hp_val(block));
  1274	      header_t hd = Hd_val(block);
  1275	
  1276	      if (Tag_hd(hd) == Infix_tag) {
  1277	        block -= Infix_offset_hd(hd);
  1278	        hd = Hd_val(block);
  1279	      }
  1280	
  1281	      CAMLassert(!Has_status_hd(hd, heap_state.GARBAGE));
  1282	      if (!Has_status_hd(hd, heap_state.UNMARKED)) {
  1283	        /* Already black, nothing to do */
  1284	        continue;
  1285	      }
  1286	      blocks_marked++;
  1287	
  1288	      if (Tag_hd(hd) == Cont_tag) {
  1289	        caml_darken_cont(block);
  1290	        budget -= Wosize_hd(hd);
  1291	        continue;
  1292	      }
  1293	
  1294	again:
  1295	      if (Tag_hd(hd) == Lazy_tag || Tag_hd(hd) == Forcing_tag) {
  1296	        if (!atomic_compare_exchange_strong(Hp_atomic_val(block), &hd,
  1297	              With_status_hd(hd, caml_global_heap_state.MARKED))) {
  1298	          hd = Hd_val(block);
  1299	          goto again;
  1300	        }
  1301	      } else {
  1302	        atomic_store_relaxed(
  1303	            Hp_atomic_val(block),
  1304	            With_status_hd(hd, caml_global_heap_state.MARKED));
  1305	      }
  1306	
  1307	      budget--; /* header word */
  1308	      if (Tag_hd(hd) >= No_scan_tag) {
  1309	        /* Nothing to scan here */
  1310	        budget -= Wosize_hd(hd);
  1311	        continue;
  1312	      }
  1313	
  1314	      me.start = Op_val(block);
  1315	      me.end = me.start + Wosize_hd(hd);
  1316	
  1317	      if (Tag_hd(hd) == Closure_tag) {
  1318	        uintnat env_offset = Start_env_closinfo(Closinfo_val(block));
  1319	        budget -= env_offset;
  1320	        me.start += env_offset;
  1321	      }
  1322	    }
  1323	    else if (budget <= 0 || stk->count == 0) {
  1324	      if (pb.waterline > 0) {
  1325	        /* Dequeue from pb even when close to empty, because
  1326	           we have nothing else to do */
  1327	        pb_drain_mode(&pb);
  1328	        continue;
  1329	      }
  1330	      else {
  1331	        /* Couldn't find work with pb in draining mode,
  1332	           so there's nothing to do */
  1333	        break;
  1334	      }
  1335	    }
  1336	    else {
  1337	      me = stk->stack[--stk->count];
  1338	    }
  1339	
  1340	    value_ptr scan_end = me.end;
  1341	    if (scan_end - me.start > budget) {
  1342	      intnat scan_len = budget < 0 ? 0 : budget;
  1343	      scan_end = me.start + scan_len;
  1344	    }
  1345	
  1346	    for (; me.start < scan_end; me.start++) {
  1347	      CAMLassert(budget >= 0);
  1348	
  1349	      value child = volatile_load_uninstrumented(me.start);
  1350	
  1351	      budget--;
  1352	      if (Is_markable(child)) {
  1353	        if (pb_full(&pb))
  1354	          break;
  1355	        prefetch_block(child);
  1356	        pb_push(&pb, child);
  1357	      }
  1358	    }
  1359	
  1360	    if (me.start < me.end) {
  1361	      /* Didn't finish scanning this object, either because budget <= 0,
  1362	         or the prefetch buffer filled up. Leave the rest on the stack. */
  1363	      mark_stack_push_range(stk, me.start, me.end);
  1364	      caml_prefetch((void*)(me.start + 1));
  1365	
  1366	      if (pb_size(&pb) > PREFETCH_BUFFER_MIN) {
  1367	        /* We may have just discovered more work when we were about to run out.
  1368	           Reset waterline so that we try to refill the buffer again. */
  1369	        pb_fill_mode(&pb);
  1370	      }
  1371	    }
  1372	  }
  1373	
  1374	  Caml_state->stat_blocks_marked += blocks_marked;
  1375	  CAMLassert(pb_size(&pb) == 0);
  1376	  return budget;
  1377	}
  1378	
  1379	/* mark until the budget runs out or marking is done */
  1380	static intnat mark(intnat budget) {
  1381	  caml_domain_state *domain_state = Caml_state;
  1382	  while (budget > 0 && !domain_state->marking_done) {
  1383	    budget = do_some_marking(domain_state->mark_stack, budget);
  1384	    if (budget > 0) {
  1385	      struct mark_stack* mstk = domain_state->mark_stack;
  1386	      addrmap_iterator it = mstk->compressed_stack_iter;
  1387	      if (caml_addrmap_iter_ok(&mstk->compressed_stack, it)) {
  1388	        uintnat chunk = caml_addrmap_iter_key(&mstk->compressed_stack, it);
  1389	        uintnat bitset = caml_addrmap_iter_value(&mstk->compressed_stack, it);
  1390	
  1391	        /* NB: must update the iterator here, as possible that
  1392	           mark_slice_darken could lead to the mark stack being pruned
  1393	           and invalidation of the iterator */
  1394	        mstk->compressed_stack_iter =
  1395	                      caml_addrmap_next(&mstk->compressed_stack, it);
  1396	
  1397	        for(int ofs=0; ofs<BITS_PER_WORD; ofs++) {
  1398	          if(bitset & ((uintnat)1 << ofs)) {
  1399	            value_ptr p = chunk_and_offset_to_ptr(chunk, ofs);
  1400	            mark_slice_darken(domain_state->mark_stack, *p, &budget);
  1401	          }
  1402	        }
  1403	      } else {
  1404	        ephe_next_cycle ();
  1405	        domain_state->marking_done = 1;
  1406	        (void)caml_atomic_counter_decr(&num_domains_to_mark);
  1407	      }
  1408	    }
  1409	  }
  1410	  return budget;
  1411	}
