  1413	static scanning_action_flags darken_scanning_flags = 0;
  1414	
  1415	void caml_darken_cont(value cont)
  1416	{
  1417	  CAMLassert(Is_block(cont));
  1418	  CAMLassert(!Is_young(cont));
  1419	  CAMLassert(Tag_val(cont) == Cont_tag);
  1420	  {
  1421	    SPIN_WAIT {
  1422	      header_t hd = atomic_load_relaxed(Hp_atomic_val(cont));
  1423	      CAMLassert(!Has_status_hd(hd, caml_global_heap_state.GARBAGE));
  1424	      if (Has_status_hd(hd, caml_global_heap_state.MARKED)) {
  1425	        /* Perform an acquire load to synchronize with the marking domain */
  1426	        hd = atomic_load_acquire(Hp_atomic_val(cont));
  1427	        if (Has_status_hd(hd, caml_global_heap_state.MARKED))
  1428	          break;
  1429	      }
  1430	      if (Has_status_hd(hd, caml_global_heap_state.UNMARKED) &&
  1431	          atomic_compare_exchange_strong(
  1432	              Hp_atomic_val(cont), &hd,
  1433	              With_status_hd(hd, NOT_MARKABLE))) {
  1434	        value stk = Field(cont, 0);
  1435	        if (Ptr_val(stk) != NULL)
  1436	          caml_scan_stack(&caml_darken, darken_scanning_flags, Caml_state,
  1437	                          Ptr_val(stk), 0);
  1438	        atomic_store_release(Hp_atomic_val(cont),
  1439	                             With_status_hd(hd, caml_global_heap_state.MARKED));
  1440	      }
  1441	    }
  1442	  }
  1443	}
  1444	
  1445	void caml_darken(void* state, value v, volatile value* ignored) {
  1446	  header_t hd;
  1447	  if (!Is_markable (v)) return; /* foreign stack, at least */
  1448	
  1449	  hd = Hd_val(v);
  1450	  if (Tag_hd(hd) == Infix_tag) {
  1451	    v -= Infix_offset_hd(hd);
  1452	    hd = Hd_val(v);
  1453	  }
  1454	  if (Has_status_hd(hd, caml_global_heap_state.UNMARKED)) {
  1455	    caml_domain_state* domain_state = (caml_domain_state*)state;
  1456	    if (domain_state->marking_done) {
  1457	      (void)caml_atomic_counter_incr(&num_domains_to_mark);
  1458	      domain_state->marking_done = 0;
  1459	    }
  1460	    if (Tag_hd(hd) == Cont_tag) {
  1461	      caml_darken_cont(v);
  1462	    } else {
  1463	      atomic_store_relaxed(
  1464	         Hp_atomic_val(v),
  1465	         With_status_hd(hd, caml_global_heap_state.MARKED));
  1466	      if (Tag_hd(hd) < No_scan_tag) {
  1467	        mark_stack_push_block(domain_state->mark_stack, v);
  1468	      }
  1469	    }
  1470	  }
  1471	}
