  1475	 ******************************************************************************/
  1476	
  1477	static void cycle_major_heap_from_stw_single(
  1478	  caml_domain_state* domain,
  1479	  uintnat num_domains_in_stw)
  1480	{
  1481	  /* Cycle major heap */
  1482	  /* FIXME: delete caml_cycle_heap_from_stw_single
  1483	     and have per-domain copies of the data? */
  1484	  caml_cycle_heap_from_stw_single();
  1485	  caml_gc_log("GC cycle %" CAML_PRIuNAT " completed (heap cycled)",
  1486	              caml_major_cycles_completed);
  1487	
  1488	  caml_major_cycles_completed++;
  1489	  CAML_GC_MESSAGE(SLICESIZE, "Starting major GC cycle\n");
  1490	
  1491	  if (atomic_load_relaxed(&caml_verb_gc) & CAML_GC_MSG_STATS) {
  1492	    struct gc_stats s;
  1493	    intnat heap_words, not_garbage_words, swept_words;
  1494	
  1495	    caml_compute_gc_stats(&s);
  1496	    heap_words = s.heap_stats.pool_words + s.heap_stats.large_words;
  1497	    not_garbage_words = s.heap_stats.pool_live_words
  1498	      + s.heap_stats.large_words;
  1499	    swept_words = domain->swept_words;
  1500	    caml_gc_log ("heap_words: %" CAML_PRIdNAT " "
  1501	                 "not_garbage_words %" CAML_PRIdNAT " "
  1502	                 "swept_words %" CAML_PRIdNAT,
  1503	                 heap_words, not_garbage_words, swept_words);
  1504	
  1505	    static struct {
  1506	      intnat heap_words;
  1507	      intnat not_garbage_words;
  1508	    } last_cycle = {0, 0};
  1509	
  1510	    if (last_cycle.heap_words != 0) {
  1511	      /* At the end of a major cycle, no object has colour MARKED.
  1512	
  1513	         [not_garbage_words] counts all objects which are UNMARKED.
  1514	         Importantly, this includes both live objects and objects which are
  1515	         unreachable in the current cycle (i.e, garbage). But we don't get
  1516	         to know which objects are garbage until the end of the next cycle.
  1517	
  1518	         live_words@N = not_garbage_words@N - swept_words@N+1
  1519	
  1520	         space_overhead@N =
  1521	         100.0 * (heap_words@N - live_words@N) / live_words@N
  1522	      */
  1523	      intnat live_words = last_cycle.not_garbage_words - swept_words;
  1524	      double space_overhead = 100.0 * (double)(last_cycle.heap_words
  1525	                                               - live_words) / live_words;
  1526	
  1527	      caml_gc_log("Previous cycle's space_overhead: %lf", space_overhead);
  1528	    }
  1529	    last_cycle.heap_words = heap_words;
  1530	    last_cycle.not_garbage_words = not_garbage_words;
  1531	  }
  1532	
  1533	  domain->swept_words = 0;
  1534	
  1535	  caml_atomic_counter_init(&num_domains_to_sweep, num_domains_in_stw);
  1536	  caml_atomic_counter_init(&num_domains_to_mark, num_domains_in_stw);
  1537	
  1538	  caml_gc_phase = Phase_sweep_and_mark_main;
  1539	  caml_atomic_counter_init(&ephe_cycle_info.num_domains_todo,
  1540	                           num_domains_in_stw);
  1541	  caml_atomic_counter_init(&ephe_cycle_info.ephe_cycle, 1);
  1542	  caml_atomic_counter_init(&ephe_cycle_info.num_domains_done, 0);
  1543	
  1544	  caml_atomic_counter_init(&num_domains_to_ephe_sweep, 0);
  1545	  /* Will be set to the correct number when switching to
  1546	     [Phase_sweep_ephe] */
  1547	
  1548	  caml_atomic_counter_init(&num_domains_to_final_update_first,
  1549	                           num_domains_in_stw);
  1550	  caml_atomic_counter_init(&num_domains_to_final_update_last,
  1551	                           num_domains_in_stw);
  1552	
  1553	  atomic_store(&domain_global_roots_started, WORK_UNSTARTED);
  1554	
  1555	  caml_code_fragment_cleanup_from_stw_single();
  1556	}
  1557	
  1558	struct cycle_callback_params {
  1559	  int force_compaction;
  1560	};
  1561	
  1562	static void stw_cycle_all_domains(
  1563	  caml_domain_state* domain, void* args,
  1564	  int participating_count,
  1565	  caml_domain_state** participating)
  1566	{
  1567	  /* We copy params because the stw leader may leave early. No barrier needed
  1568	     because there's one in the minor gc and after. */
  1569	  struct cycle_callback_params params = *((struct cycle_callback_params*)args);
  1570	
  1571	  /* TODO: Not clear this memprof work is really part of the "cycle"
  1572	   * operation. It's more like ephemeron-cleaning really. An earlier
  1573	   * version had a separate callback for this, but resulted in
  1574	   * failures because using caml_try_run_on_all_domains() on it would
  1575	   * mysteriously put all domains back into mark/sweep.
  1576	   */
  1577	  CAML_EV_BEGIN(EV_MAJOR_MEMPROF_CLEAN);
  1578	  caml_memprof_after_major_gc(domain);
  1579	  CAML_EV_END(EV_MAJOR_MEMPROF_CLEAN);
  1580	
  1581	  CAML_EV_BEGIN(EV_MAJOR_GC_CYCLE_DOMAINS);
  1582	
  1583	  CAMLassert(domain == Caml_state);
  1584	  CAMLassert(caml_atomic_counter_value(&ephe_cycle_info.num_domains_todo) ==
  1585	             caml_atomic_counter_value(&ephe_cycle_info.num_domains_done));
  1586	  CAMLassert(caml_atomic_counter_value(&num_domains_to_mark) == 0);
  1587	  CAMLassert(caml_atomic_counter_value(&num_domains_to_sweep) == 0);
  1588	  CAMLassert(caml_atomic_counter_value(&num_domains_to_ephe_sweep) == 0);
  1589	
  1590	  caml_empty_minor_heap_no_major_slice_from_stw
  1591	                        (domain, (void*)0, participating_count, participating);
  1592	
  1593	  CAML_EV_BEGIN(EV_MAJOR_GC_STW);
  1594	  Caml_global_barrier_if_final(participating_count) {
  1595	    cycle_major_heap_from_stw_single(domain, (uintnat) participating_count);
  1596	  }
  1597	
  1598	  /* If the heap is to be verified, do it before the domains continue
  1599	     running OCaml code. */
  1600	  if (caml_params->verify_heap) {
  1601	    caml_verify_heap_from_stw(domain);
  1602	    caml_gc_log("Heap verified");
  1603	    /* This global barrier avoids races between the verify_heap code
  1604	       and the rest of the STW critical section, for example the parts
  1605	       that mark global roots. */
  1606	    caml_global_barrier(participating_count);
  1607	  }
  1608	
  1609	  caml_cycle_heap(domain->shared_heap);
  1610	
  1611	  /* Compact here if requested (or, in some future version, if the heap overhead
  1612	      is too high). */
  1613	  if (params.force_compaction) {
  1614	    caml_compact_heap(domain, participating_count, participating);
  1615	  }
  1616	
  1617	  /* Update GC stats (as these could have significantly changed if there was a
  1618	      compaction) */
  1619	  caml_collect_gc_stats_sample_stw(domain);
  1620	
  1621	  /* Collect domain-local stats to emit to runtime events */
  1622	  struct heap_stats local_stats;
  1623	  caml_collect_heap_stats_sample(Caml_state->shared_heap, &local_stats);
  1624	
  1625	  CAML_EV_COUNTER(EV_C_MAJOR_HEAP_POOL_WORDS,
  1626	                  (uintnat)local_stats.pool_words);
  1627	  CAML_EV_COUNTER(EV_C_MAJOR_HEAP_POOL_LIVE_WORDS,
  1628	                  (uintnat)local_stats.pool_live_words);
  1629	  CAML_EV_COUNTER(EV_C_MAJOR_HEAP_LARGE_WORDS,
  1630	                  (uintnat)local_stats.large_words);
  1631	  CAML_EV_COUNTER(EV_C_MAJOR_HEAP_POOL_FRAG_WORDS,
  1632	                  (uintnat)(local_stats.pool_frag_words));
  1633	  CAML_EV_COUNTER(EV_C_MAJOR_HEAP_POOL_LIVE_BLOCKS,
  1634	                  (uintnat)local_stats.pool_live_blocks);
  1635	  CAML_EV_COUNTER(EV_C_MAJOR_HEAP_LARGE_BLOCKS,
  1636	                  (uintnat)local_stats.large_blocks);
  1637	
  1638	  domain->sweeping_done = 0;
  1639	
  1640	  /* Mark roots for new cycle */
  1641	  domain->marking_done = 0;
  1642	
  1643	  CAML_EV_BEGIN(EV_MAJOR_MARK_ROOTS);
  1644	  caml_do_roots (&caml_darken, darken_scanning_flags, domain, domain, 0);
  1645	  {
  1646	    uintnat work_unstarted = WORK_UNSTARTED;
  1647	    if(atomic_compare_exchange_strong(&domain_global_roots_started,
  1648	                                      &work_unstarted,
  1649	                                      WORK_STARTED)){
  1650	        caml_scan_global_roots(&caml_darken, domain);
  1651	    }
  1652	  }
  1653	  CAML_EV_END(EV_MAJOR_MARK_ROOTS);
  1654	
  1655	  CAML_EV_BEGIN(EV_MAJOR_MEMPROF_ROOTS);
  1656	  caml_memprof_scan_roots(caml_darken, darken_scanning_flags, domain,
  1657	                          domain, false);
  1658	  CAML_EV_END(EV_MAJOR_MEMPROF_ROOTS);
  1659	
  1660	  if (domain->mark_stack->count == 0 &&
  1661	      !caml_addrmap_iter_ok(&domain->mark_stack->compressed_stack,
  1662	                            domain->mark_stack->compressed_stack_iter)
  1663	      ) {
  1664	    (void)caml_atomic_counter_decr(&num_domains_to_mark);
  1665	    domain->marking_done = 1;
  1666	  }
  1667	
  1668	  /* Ephemerons */
  1669	#ifdef DEBUG
  1670	  orph_ephe_list_verify_status (caml_global_heap_state.UNMARKED);
  1671	#endif
  1672	  /* Adopt orphaned work from domains that were spawned and terminated in the
  1673	     previous cycle. */
  1674	  adopt_orphaned_work ();
  1675	  CAMLassert(domain->ephe_info->todo == (value) NULL);
  1676	  domain->ephe_info->todo = domain->ephe_info->live;
  1677	  domain->ephe_info->live = (value) NULL;
  1678	  domain->ephe_info->must_sweep_ephe = 0;
  1679	  domain->ephe_info->cycle = 0;
  1680	  domain->ephe_info->cursor.todop = NULL;
  1681	  domain->ephe_info->cursor.cycle = 0;
  1682	  if (domain->ephe_info->todo == (value) NULL)
  1683	    ephe_todo_list_emptied();
  1684	
  1685	  /* Finalisers */
  1686	  domain->final_info->updated_first = 0;
  1687	  domain->final_info->updated_last = 0;
  1688	
  1689	  /* To ensure a mutator doesn't resume while global roots are being marked.
  1690	     Mutators can alter the set of global roots, to preserve its correctness,
  1691	     they should not run while global roots are being marked.*/
  1692	  caml_global_barrier(participating_count);
  1693	
  1694	  /* Someone should flush the allocation stats we gathered during the cycle */
  1695	  if( participating[0] == domain ) {
  1696	    CAML_EV_ALLOC_FLUSH();
  1697	  }
  1698	
  1699	  CAML_EV_END(EV_MAJOR_GC_STW);
  1700	  CAML_EV_END(EV_MAJOR_GC_CYCLE_DOMAINS);
  1701	}
  1702	
  1703	/*******************************************************************************
  1704	 * Major GC phases
  1705	 ******************************************************************************/
  1706	
  1707	static int is_complete_phase_sweep_and_mark_main (void)
  1708	{
  1709	  return
  1710	    /* Marking is done */
  1711	    caml_gc_phase == Phase_sweep_and_mark_main &&
  1712	    caml_atomic_counter_value (&num_domains_to_sweep) == 0 &&
  1713	    caml_atomic_counter_value (&num_domains_to_mark) == 0 &&
  1714	
  1715	    /* No domains are orphaning finalisers. */
  1716	    caml_atomic_counter_value (&num_domains_orphaning_finalisers) == 0 &&
  1717	
  1718	    /* Ephemeron marking is done */
  1719	    caml_atomic_counter_value(&ephe_cycle_info.num_domains_todo) ==
  1720	    caml_atomic_counter_value(&ephe_cycle_info.num_domains_done) &&
  1721	
  1722	    /* All orphaned ephemerons have been adopted */
  1723	    no_orphaned_work();
  1724	}
  1725	
  1726	static int is_complete_phase_mark_final (void)
  1727	{
  1728	  return
  1729	    /* updated finalise first values */
  1730	    caml_gc_phase == Phase_mark_final &&
  1731	    caml_atomic_counter_value (&num_domains_to_final_update_first) == 0 &&
  1732	
  1733	    /* Marking is done */
  1734	    caml_atomic_counter_value (&num_domains_to_mark) == 0 &&
  1735	
  1736	    /* Ephemeron marking is done */
  1737	    caml_atomic_counter_value(&ephe_cycle_info.num_domains_todo) ==
  1738	    caml_atomic_counter_value(&ephe_cycle_info.num_domains_done) &&
  1739	
  1740	    /* All orphaned ephemerons have been adopted */
  1741	    no_orphaned_work();
  1742	}
  1743	
  1744	static int is_complete_phase_sweep_ephe (void)
  1745	{
  1746	  return
  1747	    /* All domains have swept their ephemerons */
  1748	    caml_gc_phase == Phase_sweep_ephe &&
  1749	    caml_atomic_counter_value (&num_domains_to_ephe_sweep) == 0 &&
  1750	
  1751	    /* All domains have updated finalise last values */
  1752	    caml_atomic_counter_value (&num_domains_to_final_update_last) == 0 &&
  1753	
  1754	    /* All orphaned structures have been adopted */
  1755	    no_orphaned_work();
  1756	}
  1757	
  1758	static void stw_try_complete_gc_phase(
  1759	  caml_domain_state* domain, void* unused,
  1760	  int participant_count,
  1761	  caml_domain_state** participating)
  1762	{
  1763	  CAML_EV_BEGIN(EV_MAJOR_GC_PHASE_CHANGE);
  1764	
  1765	  Caml_global_barrier_if_final(participant_count) {
  1766	    if (is_complete_phase_sweep_and_mark_main()) {
  1767	      caml_gc_phase = Phase_mark_final;
  1768	    } else if (is_complete_phase_mark_final()) {
  1769	      caml_gc_phase = Phase_sweep_ephe;
  1770	      caml_atomic_counter_init(&num_domains_to_ephe_sweep, participant_count);
  1771	      for (int i = 0; i < participant_count; i++)
  1772	        participating[i]->ephe_info->must_sweep_ephe = 1;
  1773	    }
  1774	  }
  1775	
  1776	  CAML_EV_END(EV_MAJOR_GC_PHASE_CHANGE);
  1777	}
  1778	
  1779	/*******************************************************************************
  1780	 * Major GC slices
  1781	 ******************************************************************************/
  1782	
  1783	intnat caml_opportunistic_major_work_available (caml_domain_state* domain_state)
  1784	{
  1785	  return !domain_state->sweeping_done || !domain_state->marking_done;
  1786	}
  1787	
  1788	static char collection_slice_mode_char(collection_slice_mode mode)
  1789	{
  1790	  switch(mode) {
  1791	    case Slice_uninterruptible:
  1792	      return 'u';
  1793	    case Slice_interruptible:
  1794	      return 'i';
  1795	    case Slice_opportunistic:
  1796	      return 'o';
  1797	    default:
  1798	      return ' ';
  1799	  }
  1800	}
  1801	
  1802	static void major_collection_slice(intnat howmuch,
  1803	                                   int participant_count,
  1804	                                   caml_domain_state** barrier_participants,
  1805	                                   collection_slice_mode mode,
  1806	                                   int force_compaction)
  1807	{
  1808	  caml_domain_state* domain_state = Caml_state;
  1809	  intnat sweep_work = 0, mark_work = 0;
  1810	  uintnat blocks_marked_before = domain_state->stat_blocks_marked;
  1811	  uintnat saved_ephe_cycle;
  1812	  uintnat saved_major_cycle = caml_major_cycles_completed;
  1813	  intnat budget;
  1814	
  1815	  /* Opportunistic slices may run concurrently with gc phase updates. */
  1816	  int may_access_gc_phase = (mode != Slice_opportunistic);
  1817	
  1818	  int log_events = mode != Slice_opportunistic ||
  1819	                   (atomic_load_relaxed(&caml_verb_gc) &
  1820	                    CAML_GC_MSG_SLICESIZE);
  1821	
  1822	  update_major_slice_work(howmuch, may_access_gc_phase, log_events);
  1823	
  1824	  /* When a full slice of major GC work is done,
  1825	     or the slice is interrupted (in mode Slice_interruptible),
  1826	     get_major_slice_work(mode) will return a budget <= 0 */
  1827	
  1828	  /* shortcut out if there is no opportunistic work to be done
  1829	   * NB: needed particularly to avoid caml_ev spam when polling */
  1830	  if (mode == Slice_opportunistic &&
  1831	      !caml_opportunistic_major_work_available(domain_state)) {
  1832	    commit_major_slice_work (0);
  1833	    return;
  1834	  }
  1835	
  1836	  if (log_events) CAML_EV_BEGIN(EV_MAJOR_SLICE);
  1837	  call_timing_hook(&caml_major_slice_begin_hook);
  1838	
  1839	  if (!domain_state->sweeping_done) {
  1840	    if (log_events) CAML_EV_BEGIN(EV_MAJOR_SWEEP);
  1841	
  1842	    while (!domain_state->sweeping_done &&
  1843	           (budget = get_major_slice_work(mode)) > 0) {
  1844	      intnat left = caml_sweep(domain_state->shared_heap, budget);
  1845	      intnat work_done = budget - left;
  1846	
  1847	      sweep_work += work_done;
  1848	      commit_major_slice_work (work_done);
  1849	      if (work_done == 0) {
  1850	        domain_state->sweeping_done = 1;
  1851	        (void)caml_atomic_counter_decr(&num_domains_to_sweep);
  1852	      }
  1853	    }
  1854	
  1855	    if (log_events) CAML_EV_END(EV_MAJOR_SWEEP);
  1856	  }
  1857	
  1858	mark_again:
  1859	  if (!domain_state->marking_done &&
  1860	      get_major_slice_work(mode) > 0) {
  1861	    if (log_events) CAML_EV_BEGIN(EV_MAJOR_MARK);
  1862	
  1863	    while (!domain_state->marking_done &&
  1864	           (budget = get_major_slice_work(mode)) > 0) {
  1865	      intnat left = mark(budget);
  1866	      intnat work_done = budget - left;
  1867	      mark_work += work_done;
  1868	      commit_major_slice_work(work_done);
  1869	    }
  1870	
  1871	    if (log_events) CAML_EV_END(EV_MAJOR_MARK);
  1872	  }
  1873	
  1874	  if (mode != Slice_opportunistic) {
  1875	    /* Finalisers */
  1876	    if (caml_gc_phase == Phase_mark_final &&
  1877	        get_major_slice_work(mode) > 0 &&
  1878	        caml_final_update_first(domain_state)) {
  1879	      /* This domain has updated finalise first values */
  1880	      (void)caml_atomic_counter_decr(&num_domains_to_final_update_first);
  1881	      if (!domain_state->marking_done &&
  1882	          get_major_slice_work(mode) > 0)
  1883	        goto mark_again;
  1884	    }
  1885	
  1886	    if (caml_gc_phase == Phase_sweep_ephe &&
  1887	        get_major_slice_work(mode) > 0 &&
  1888	        caml_final_update_last(domain_state)) {
  1889	      /* This domain has updated finalise last values */
  1890	      (void)caml_atomic_counter_decr(&num_domains_to_final_update_last);
  1891	      /* Nothing has been marked while updating last */
  1892	    }
  1893	
  1894	#ifdef DEBUG
  1895	    orph_ephe_list_verify_status (caml_global_heap_state.MARKED);
  1896	#endif
  1897	    adopt_orphaned_work();
  1898	
  1899	    /* Ephemerons */
  1900	    if (caml_gc_phase != Phase_sweep_ephe) {
  1901	      /* Ephemeron Marking */
  1902	      saved_ephe_cycle = caml_atomic_counter_value(&ephe_cycle_info.ephe_cycle);
  1903	      if (domain_state->ephe_info->todo != (value) NULL &&
  1904	          saved_ephe_cycle > domain_state->ephe_info->cycle &&
  1905	          get_major_slice_work(mode) > 0) {
  1906	        CAML_EV_BEGIN(EV_MAJOR_EPHE_MARK);
  1907	
  1908	        int ephe_completed_marking = 0;
  1909	        while (domain_state->ephe_info->todo != (value) NULL &&
  1910	               saved_ephe_cycle > domain_state->ephe_info->cycle &&
  1911	               (budget = get_major_slice_work(mode)) > 0) {
  1912	          intnat left = ephe_mark(budget, saved_ephe_cycle, EPHE_MARK_DEFAULT);
  1913	          intnat work_done = budget - left;
  1914	          commit_major_slice_work (work_done);
  1915	
  1916	          // FIXME: Can we delete this?
  1917	          if (left > 0) {
  1918	            ephe_completed_marking = 1;
  1919	            break;
  1920	          }
  1921	        }
  1922	
  1923	        CAML_EV_END(EV_MAJOR_EPHE_MARK);
  1924	
  1925	        if (domain_state->ephe_info->todo == (value)NULL) {
  1926	          ephe_todo_list_emptied ();
  1927	        }
  1928	
  1929	        if (ephe_completed_marking) {
  1930	          if (!domain_state->marking_done)
  1931	            goto mark_again;
  1932	          else
  1933	            record_ephe_marking_done(saved_ephe_cycle);
  1934	        }
  1935	      }
  1936	    }
  1937	
  1938	    if (caml_gc_phase == Phase_sweep_ephe) {
  1939	      /* Ephemeron Sweeping */
  1940	
  1941	      if (domain_state->ephe_info->must_sweep_ephe) {
  1942	        /* Move the ephemerons on the live list to the todo list. This is
  1943	           needed since the live list may contain ephemerons with unmarked
  1944	           keys, which need to be cleaned. This code is executed exactly once
  1945	           per major cycle per domain. */
  1946	        domain_state->ephe_info->must_sweep_ephe = 0;
  1947	
  1948	        value e = ephe_list_tail (domain_state->ephe_info->todo);
  1949	        if (e == (value)NULL) {
  1950	          domain_state->ephe_info->todo = domain_state->ephe_info->live;
  1951	        } else {
  1952	          CAMLassert(Ephe_link(e) == (value)NULL);
  1953	          Ephe_link(e) = domain_state->ephe_info->live;
  1954	        }
  1955	        domain_state->ephe_info->live = (value)NULL;
  1956	
  1957	        /* If the todo list is empty, then the ephemeron has no sweeping work
  1958	         * to do. */
  1959	        if (domain_state->ephe_info->todo == 0) {
  1960	          (void)caml_atomic_counter_decr(&num_domains_to_ephe_sweep);
  1961	        }
  1962	      }
  1963	
  1964	      if (domain_state->ephe_info->todo != 0) {
  1965	        CAMLassert (domain_state->ephe_info->must_sweep_ephe == 0);
  1966	        /* Sweep the ephemeron todo list */
  1967	        CAML_EV_BEGIN(EV_MAJOR_EPHE_SWEEP);
  1968	
  1969	        while (domain_state->ephe_info->todo != 0 &&
  1970	               (budget = get_major_slice_work(mode)) > 0) {
  1971	          intnat left = ephe_sweep (domain_state, budget);
  1972	          intnat work_done = budget - left;
  1973	          commit_major_slice_work(work_done);
  1974	        }
  1975	
  1976	        CAML_EV_END(EV_MAJOR_EPHE_SWEEP);
  1977	        if (domain_state->ephe_info->todo == 0) {
  1978	          (void)caml_atomic_counter_decr(&num_domains_to_ephe_sweep);
  1979	        }
  1980	      }
  1981	    }
  1982	
  1983	    /* Complete GC phase */
